insert into public.items (id, slug, name, category, buy_price, sell_price, effect_description, healing_amount, restores_full_health, restores_pp, revives, capture_rate_multiplier) values
  (130, 'aspear-berry', 'Aspear Berry', 'medicine', 80, 40, 'Held in battle : When the holder is frozen, it consumes this item to thaw itself. Used on a party Pokémon : Cures freezing.', null, false, false, false, null),
  (887, 'beast-ball', 'Beast Ball', 'poke_ball', 0, 0, 'Used in battle : Attempts to catch a wild Pokémon. If the wild Pokémon is an Ultra Beast, this ball has a catch rate of 5×. Otherwise, it has a catch rate of 0.1×. If used in a trainer battle, nothing happens and the ball is lost.', null, false, true, false, 1),
  (43, 'berry-juice', 'Berry Juice', 'medicine', 200, 100, 'Used on a party Pokémon : Restores 20 HP.', 20, false, false, false, null),
  (126, 'cheri-berry', 'Cheri Berry', 'medicine', 80, 40, 'Held in battle : When the holder is paralyzed, it consumes this item to cure the paralysis. Used on a party Pokémon : Cures paralysis.', null, false, false, false, null),
  (16, 'cherish-ball', 'Cherish Ball', 'poke_ball', 0, 0, 'Used in battle : Attempts to catch a wild Pokémon, using a catch rate of 1×. If used in a trainer battle, nothing happens and the ball is lost.', null, false, true, false, 1),
  (127, 'chesto-berry', 'Chesto Berry', 'medicine', 80, 40, 'Held in battle : When the holder is asleep, it consumes this item to wake up. Used on a party Pokémon : Cures sleep.', null, false, false, false, null),
  (109, 'dawn-stone', 'Dawn Stone', 'evolution_stone', 3000, 1500, 'Used on a party Pokémon : Evolves a male Kirlia into Gallade or a female Snorunt into Froslass.', null, false, false, false, null),
  (7, 'dive-ball', 'Dive Ball', 'poke_ball', 1000, 500, 'Used in battle : Attempts to catch a wild Pokémon. If the wild Pokémon was encountered by surfing or fishing, this ball has a catch rate of 3.5×. Otherwise, it has a catch rate of 1×. If used in a trainer battle, nothing happens and the ball is lost.', null, false, true, false, 1),
  (617, 'dream-ball', 'Dream Ball', 'poke_ball', 0, 0, 'Can only be used in Entree Forest, to catch Pokémon encountered in the Dream World. Used in battle : Catches a wild Pokémon without fail.', null, false, false, false, 1),
  (13, 'dusk-ball', 'Dusk Ball', 'poke_ball', 1000, 500, 'Used in battle : Attempts to catch a wild Pokémon. If it’s currently nighttime or the wild Pokémon was encountered while walking in a cave, this ball has a catch rate of 3.5×. Otherwise, it has a catch rate of 1×. If used in a trainer battle, nothing happens and the ball is lost.', null, false, true, false, 1),
  (108, 'dusk-stone', 'Dusk Stone', 'evolution_stone', 3000, 1500, 'Used on a party Pokémon : Evolves a Lampent into Chandelure, a Misdreavus into Mismagius, or a Murkrow into Honchkrow.', null, false, false, false, null),
  (34, 'energy-powder', 'Energy Powder', 'medicine', 500, 250, 'Used on a party Pokémon : Restores 50 HP. Decreases happiness by 5/5/10.', 50, false, true, false, null),
  (35, 'energy-root', 'Energy Root', 'medicine', 1200, 600, 'Used on a party Pokémon : Restores 200 HP. Decreases happiness by 10/10/15.', 200, false, true, false, null),
  (453, 'fast-ball', 'Fast Ball', 'poke_ball', 0, 0, 'Used by a trainer in battle : Attempts to catch a wild Pokémon. If used in a trainer battle, nothing happens and the ball is lost. : If the wild Pokémon’s base speed is 100 or more, its catch rate is 4× normal.', null, false, true, false, 1),
  (82, 'fire-stone', 'Fire Stone', 'evolution_stone', 3000, 1500, 'Used on a party Pokémon : Evolves an Eevee into Flareon, a Growlithe into Arcanine, a Pansear into Simisear, or a Vulpix into Ninetales.', null, false, false, false, null),
  (30, 'fresh-water', 'Fresh Water', 'medicine', 200, 100, 'Used on a party Pokémon : Restores 50 HP.', 50, false, false, false, null),
  (454, 'friend-ball', 'Friend Ball', 'poke_ball', 0, 0, 'Used by a trainer in battle : Attempts to catch a wild Pokémon. If used in a trainer battle, nothing happens and the ball is lost. If caught, the wild Pokémon’s happiness starts at 200.', null, false, true, false, 1),
  (23, 'full-restore', 'Full Restore', 'medicine', 3000, 1500, 'Used on a party Pokémon : Restores HP to full and cures any status ailment and confusion.', null, true, false, false, null),
  (3, 'great-ball', 'Great Ball', 'poke_ball', 600, 300, 'Used in battle : Attempts to catch a wild Pokémon, using a catch rate of 1.5×. If used in a trainer battle, nothing happens and the ball is lost.', null, false, true, false, 1),
  (14, 'heal-ball', 'Heal Ball', 'poke_ball', 300, 150, 'Used in battle : Attempts to catch a wild Pokémon, using a catch rate of 1×. The caught Pokémon’s HP is immediately restored, PP for all its moves is restored, and any status ailment is cured. If used in a trainer battle, nothing happens and the ball is lost.', null, false, true, false, 1),
  (452, 'heavy-ball', 'Heavy Ball', 'poke_ball', 0, 0, 'Used by a trainer in battle : Attempts to catch a wild Pokémon. If used in a trainer battle, nothing happens and the ball is lost. If the wild Pokémon weighs: * 409.6 kg (903.0 lb) or more, its catch rate is 40 more than normal. * 307.2 kg (677.3 lb) or more, its catch rate is 30 more than normal. * 204.8 kg (451.5 lb) or more, its catch rate is 20 more than normal. * less than 204.8 kg (451.5 lb), its catch rate is 20 less than normal.', null, false, true, false, 1),
  (25, 'hyper-potion', 'Hyper Potion', 'medicine', 1500, 750, 'Used on a party Pokémon : Restores 200 HP.', 200, false, false, false, null),
  (885, 'ice-stone', 'Ice Stone', 'evolution_stone', 3000, 1500, 'Used on a party Pokémon : Evolves an Alola Sandshrew into Alola Sandslash or an Alola Vulpix into Alola Ninetales.', null, false, false, false, null),
  (2226, 'lafeather-ball', 'Lafeather Ball', 'poke_ball', 0, 0, 'No effect description is available.', null, false, false, false, 1),
  (2225, 'lagigaton-ball', 'Lagigaton Ball', 'poke_ball', 0, 0, 'No effect description is available.', null, false, false, false, 1),
  (2221, 'lagreat-ball', 'Lagreat Ball', 'poke_ball', 0, 0, 'No effect description is available.', null, false, false, false, 1),
  (2223, 'laheavy-ball', 'Laheavy Ball', 'poke_ball', 0, 0, 'No effect description is available.', null, false, false, false, 1),
  (2228, 'lajet-ball', 'Lajet Ball', 'poke_ball', 0, 0, 'No effect description is available.', null, false, false, false, 1),
  (2224, 'laleaden-ball', 'Laleaden Ball', 'poke_ball', 0, 0, 'No effect description is available.', null, false, false, false, 1),
  (2229, 'laorigin-ball', 'Laorigin Ball', 'poke_ball', 0, 0, 'No effect description is available.', null, false, false, false, 1),
  (2220, 'lapoke-ball', 'Lapoke Ball', 'poke_ball', 0, 0, 'No effect description is available.', null, false, false, false, 1),
  (2219, 'lastrange-ball', 'Lastrange Ball', 'poke_ball', 0, 0, 'No effect description is available.', null, false, false, false, 1),
  (2222, 'laultra-ball', 'Laultra Ball', 'poke_ball', 0, 0, 'No effect description is available.', null, false, false, false, 1),
  (2227, 'lawing-ball', 'Lawing Ball', 'poke_ball', 0, 0, 'No effect description is available.', null, false, false, false, 1),
  (85, 'leaf-stone', 'Leaf Stone', 'evolution_stone', 3000, 1500, 'Used on a party Pokémon : Evolves an Exeggcute into Exeggutor, a Gloom into Vileplume, a Nuzleaf into Shiftry, a Pansage into Simisage, or a Weepinbell into Victreebel.', null, false, false, false, null),
  (32, 'lemonade', 'Lemonade', 'medicine', 400, 200, 'Used on a party Pokémon : Restores 80 HP.', 80, false, false, false, null),
  (131, 'leppa-berry', 'Leppa Berry', 'medicine', 80, 40, 'Held in battle : When the holder is out of PP for one of its moves, it consumes this item to restore 10 of that move’s PP. Used on a party Pokémon : Restores 10 PP for a selected move.', null, false, true, false, null),
  (450, 'level-ball', 'Level Ball', 'poke_ball', 0, 0, 'Used by trainer in battle : Attempts to catch a wild Pokémon. If used in a trainer battle, nothing happens and the ball is lost. If the trainer’s Pokémon’s level is higher than: * four times the wild Pokémon’s, the wild Pokémon’s catch rate is 8× normal. * than twice the wild Pokémon’s, the wild Pokémon’s catch rate is 4× normal. * the wild Pokémon’s, the wild Pokémon’s catch rate is 2× normal.', null, false, true, false, 1),
  (455, 'love-ball', 'Love Ball', 'poke_ball', 0, 0, 'Used by a trainer in battle : Attempts to catch a wild Pokémon. If used in a trainer battle, nothing happens and the ball is lost. If the trainer’s Pokémon and wild Pokémon are of the same species but opposite genders, the wild Pokémon’s catch rate is 8× normal.', null, false, true, false, 1),
  (134, 'lum-berry', 'Lum Berry', 'medicine', 80, 40, 'Held in battle : When the holder is afflicted with a major status ailment, it consumes this item to cure the ailment. Used on a party Pokémon : Cures any major status ailment.', null, false, false, false, null),
  (449, 'lure-ball', 'Lure Ball', 'poke_ball', 0, 0, 'Used by trainer in battle : Attempts to catch a wild Pokémon. If used in a trainer battle, nothing happens and the ball is lost. If the wild Pokémon was encountered by fishing, the wild Pokémon’s catch rate is 3× normal.', null, false, true, false, 1),
  (11, 'luxury-ball', 'Luxury Ball', 'poke_ball', 3000, 1500, 'Used in battle : Attempts to catch a wild Pokémon, using a catch rate of 1×. Whenever the caught Pokémon’s happiness increases, it increases by one extra point. If used in a trainer battle, nothing happens and the ball is lost.', null, false, true, false, 1),
  (1, 'master-ball', 'Master Ball', 'poke_ball', 0, 0, 'Used in battle : Catches a wild Pokémon without fail. If used in a trainer battle, nothing happens and the ball is lost.', null, false, true, false, 255),
  (24, 'max-potion', 'Max Potion', 'medicine', 2500, 1250, 'Used on a party Pokémon : Restores HP to full.', null, true, false, false, null),
  (33, 'moomoo-milk', 'Moomoo Milk', 'medicine', 600, 300, 'Used on a party Pokémon : Restores 100 HP.', 100, false, false, false, null),
  (451, 'moon-ball', 'Moon Ball', 'poke_ball', 0, 0, 'Used by trainer in battle : Attempts to catch a wild Pokémon. If used in a trainer battle, nothing happens and the ball is lost. If the wild Pokémon is a Clefairy, Nidoran♂, Nidoran♀, Jigglypuff, Skitty, or any evolution thereof, the wild Pokémon has 4× its catch rate.', null, false, true, false, 1),
  (81, 'moon-stone', 'Moon Stone', 'evolution_stone', 3000, 1500, 'Used on a party Pokémon : Evolves a Clefairy into Clefable, a Jigglypuff into Wigglytuff, a Munna into Musharna, a Nidorina into Nidoqueen, a Nidorino into Nidoking, or a Skitty into Delcatty.', null, false, false, false, null),
  (8, 'nest-ball', 'Nest Ball', 'poke_ball', 1000, 500, 'Used in battle : Attempts to catch a wild Pokémon. Has a catch rate of given by `(40 - level) / 10`, where `level` is the wild Pokémon’s level, to a maximum of 3.9× for level 1 Pokémon. If the wild Pokémon’s level is higher than 30, this ball has a catch rate of 1×. If used in a trainer battle, nothing happens and the ball is lost.', null, false, true, false, 1),
  (6, 'net-ball', 'Net Ball', 'poke_ball', 1000, 500, 'Used in battle : Attempts to catch a wild Pokémon. If the wild Pokémon is Water- or Bug-type, this ball has a catch rate of 3×. Otherwise, it has a catch rate of 1×. If used in a trainer battle, nothing happens and the ball is lost.', null, false, true, false, 1),
  (132, 'oran-berry', 'Oran Berry', 'medicine', 80, 40, 'Held in battle : When the holder has 1/2 its max HP remaining or less, it consumes this item to restore 10 HP. Used on a party Pokémon : Restores 10 HP.', 10, false, false, false, null),
  (110, 'oval-stone', 'Oval Stone', 'evolution_stone', 2000, 1000, 'Held by Happiny : Holder evolves into Chansey when it levels up during the daytime.', null, false, true, false, null),
  (456, 'park-ball', 'Park Ball', 'poke_ball', 0, 0, 'Used by a trainer in battle : Catches a wild Pokémon. This item can only be used in Pal Park.', null, false, false, false, 1),
  (128, 'pecha-berry', 'Pecha Berry', 'medicine', 80, 40, 'Held in battle : When the holder is poisoned, it consumes this item to cure the poison. Used on a party Pokémon : Cures poison.', null, false, false, false, null),
  (133, 'persim-berry', 'Persim Berry', 'medicine', 80, 40, 'Held in battle : When the holder is confused, it consumes this item to cure the confusion. Used on a party Pokémon : Cures confusion.', null, false, false, false, null),
  (4, 'poke-ball', 'Poke Ball', 'poke_ball', 200, 100, 'Used in battle : Attempts to catch a wild Pokémon, using a catch rate of 1×. If used in a trainer battle, nothing happens and the ball is lost.', null, false, true, false, 1),
  (17, 'potion', 'Potion', 'medicine', 200, 100, 'Used on a friendly Pokémon : Restores 20 HP.', 20, false, false, false, null),
  (12, 'premier-ball', 'Premier Ball', 'poke_ball', 20, 10, 'Used in battle : Attempts to catch a wild Pokémon, using a catch rate of 1×. If used in a trainer battle, nothing happens and the ball is lost.', null, false, true, false, 1),
  (15, 'quick-ball', 'Quick Ball', 'poke_ball', 1000, 500, 'Used in battle : Attempts to catch a wild Pokémon, using a catch rate of 4× on the first turn of a battle, but 1× any other time. If used in a trainer battle, nothing happens and the ball is lost.', null, false, true, false, 1),
  (129, 'rawst-berry', 'Rawst Berry', 'medicine', 80, 40, 'Held in battle : When the holder is burned, it consumes this item to cure the burn. Used on a party Pokémon : Cures a burn.', null, false, false, false, null),
  (9, 'repeat-ball', 'Repeat Ball', 'poke_ball', 1000, 500, 'Used in battle : Attempts to catch a wild Pokémon. If the wild Pokémon’s species is marked as caught in the trainer’s Pokédex, this ball has a catch rate of 3×. Otherwise, it has a catch rate of 1×. If used in a trainer battle, nothing happens and the ball is lost.', null, false, true, false, 1),
  (5, 'safari-ball', 'Safari Ball', 'poke_ball', 0, 0, 'Used in battle : Attempts to catch a wild Pokémon, using a catch rate of 1.5×. This item can only be used in the Great Marsh or Safari Zone.', null, false, false, false, 1),
  (107, 'shiny-stone', 'Shiny Stone', 'evolution_stone', 3000, 1500, 'Used on a party Pokémon : Evolves a Minccino into Cinccino, a Roselia into Roserade, or a Togetic into Togekiss.', null, false, false, false, null),
  (135, 'sitrus-berry', 'Sitrus Berry', 'medicine', 80, 40, 'Held in battle : When the holder has 1/2 its max HP remaining or less, it consumes this item to restore 1/4 its max HP. Used on a party Pokémon : Restores 1/4 the Pokémon’s max HP.', null, false, false, false, null),
  (31, 'soda-pop', 'Soda Pop', 'medicine', 300, 150, 'Used on a party Pokémon : Restores 60 HP.', 60, false, false, false, null),
  (457, 'sport-ball', 'Sport Ball', 'poke_ball', 300, 150, 'Used by a trainer in battle : Attempts to catch a wild Pokémon. The wild Pokémon’s catch rate is 1.5× normal.', null, false, false, false, 1),
  (80, 'sun-stone', 'Sun Stone', 'evolution_stone', 3000, 1500, 'Used on a party Pokémon : Evolves a Cottonee into Whimsicott, a Gloom into Bellossom, a Petilil into Lilligant, or a Sunkern into Sunflora.', null, false, false, false, null),
  (26, 'super-potion', 'Super Potion', 'medicine', 700, 350, 'Used on a party Pokémon : Restores 50 HP.', 50, false, false, false, null),
  (567, 'sweet-heart', 'Sweet Heart', 'medicine', 3000, 1500, 'Used on a friendly Pokémon : Restores 20 HP.', 20, false, false, false, null),
  (83, 'thunder-stone', 'Thunder Stone', 'evolution_stone', 3000, 1500, 'Used on a party Pokémon : Evolves an Eelektrik into Eelektross, an Eevee into Jolteon, or a Pikachu into Raichu.', null, false, false, false, null),
  (10, 'timer-ball', 'Timer Ball', 'poke_ball', 1000, 500, 'Used in battle : Attempts to catch a wild Pokémon. Has a catch rate of 1.1× on the first turn of the battle and increases by 0.1× every turn, to a maximum of 4× on turn 30. If used in a trainer battle, nothing happens and the ball is lost.', null, false, true, false, 1),
  (2, 'ultra-ball', 'Ultra Ball', 'poke_ball', 800, 400, 'Used in battle : Attempts to catch a wild Pokémon, using a catch rate of 2×. If used in a trainer battle, nothing happens and the ball is lost.', null, false, true, false, 1),
  (84, 'water-stone', 'Water Stone', 'evolution_stone', 3000, 1500, 'Used on a party Pokémon : Evolves an Eevee into Vaporeon, a Lombre into Ludicolo, a Panpour into Simipour, a Poliwhirl into Poliwrath, a Shellder into Cloyster, or a Staryu into Starmie.', null, false, false, false, null)
