insert into public.moves (id, slug, name, type_id, category, power, accuracy, base_pp, priority, effect_description, cooldown_ms, delivery, target, area_shape, range_tiles, area_radius, area_length, area_width) values
  (1, 'pound', 'Pound', 1, 'physical', 40, 100, 35, 0, 'Inflicts regular damage.', 1600, 'melee', 'unit', 'single', 1, 0, 0, 0),
  (2, 'karate-chop', 'Karate Chop', 7, 'physical', 50, 100, 25, 0, 'Inflicts regular damage. User’s critical hit rate is one level higher when using this move.', 1800, 'melee', 'unit', 'single', 1, 0, 0, 0),
  (3, 'double-slap', 'Double Slap', 1, 'physical', 15, 85, 10, 0, 'Inflicts regular damage. Hits 2–5 times in one turn. Has a 3/8 chance each to hit 2 or 3 times, and a 1/8 chance each to hit 4 or 5 times. Averages to 3 hits per use.', 1300, 'melee', 'unit', 'single', 1, 0, 0, 0),
  (4, 'comet-punch', 'Comet Punch', 1, 'physical', 18, 85, 15, 0, 'Inflicts regular damage. Hits 2–5 times in one turn. Has a 3/8 chance each to hit 2 or 3 times, and a 1/8 chance each to hit 4 or 5 times. Averages to 3 hits per use.', 1300, 'melee', 'unit', 'single', 1, 0, 0, 0),
  (5, 'mega-punch', 'Mega Punch', 1, 'physical', 80, 85, 20, 0, 'Inflicts regular damage.', 2100, 'melee', 'unit', 'single', 1, 0, 0, 0),
  (6, 'pay-day', 'Pay Day', 1, 'physical', 40, 100, 20, 0, 'Inflicts regular damage. After the battle ends, the winner receives five times the user’s level in extra money for each time this move was used.', 1600, 'melee', 'unit', 'single', 1, 0, 0, 0),
  (7, 'fire-punch', 'Fire Punch', 2, 'special', 75, 100, 15, 0, 'Inflicts regular damage. Has a chance to burn the target.', 2600, 'ranged', 'unit', 'single', 4, 0, 0, 0),
  (8, 'ice-punch', 'Ice Punch', 6, 'special', 75, 100, 15, 0, 'Inflicts regular damage. Has a chance to freeze the target.', 2600, 'ranged', 'unit', 'single', 4, 0, 0, 0),
  (9, 'thunder-punch', 'Thunder Punch', 4, 'special', 75, 100, 15, 0, 'Inflicts regular damage. Has a chance to paralyze the target.', 2600, 'ranged', 'unit', 'single', 4, 0, 0, 0),
  (10, 'scratch', 'Scratch', 1, 'physical', 40, 100, 35, 0, 'Inflicts regular damage.', 1600, 'melee', 'unit', 'single', 1, 0, 0, 0),
  (11, 'vice-grip', 'Vice Grip', 1, 'physical', 55, 100, 30, 0, 'Inflicts regular damage.', 1800, 'melee', 'unit', 'single', 1, 0, 0, 0),
  (12, 'guillotine', 'Guillotine', 1, 'physical', null, 30, 5, 0, 'Inflicts damage equal to the target’s max HP. Ignores accuracy and evasion modifiers. This move’s accuracy is 30% plus 1% for each level the user is higher than the target. If the user is a lower level than the target, this move will fail. Because this move inflicts a specific and finite amount of damage, Endure still prevents the target from fainting. The effects of Lock-On, Mind Reader, and No Guard still apply, as long as the user is equal or higher level than the target. However, they will not give this move a chance to break through Detect or Protect.', 1000, 'melee', 'unit', 'single', 1, 0, 0, 0),
  (13, 'razor-wind', 'Razor Wind', 1, 'physical', 80, 100, 10, 0, 'Inflicts regular damage. User’s critical hit rate is one level higher when using this move. User charges for one turn before attacking. This move cannot be selected by Sleep Talk.', 3900, 'melee', 'unit', 'single', 1, 0, 0, 0),
  (14, 'swords-dance', 'Swords Dance', 1, 'status', null, null, 20, 0, 'Raises the user’s Attack by two stages.', 2500, 'melee', 'self', 'single', 0, 0, 0, 0),
  (15, 'cut', 'Cut', 1, 'physical', 50, 95, 30, 0, 'Inflicts regular damage.', 1800, 'melee', 'unit', 'single', 1, 0, 0, 0),
  (16, 'gust', 'Gust', 10, 'physical', 40, 100, 35, 0, 'Inflicts regular damage. If the target is under the effect of Bounce, Fly, or Sky Drop, this move will hit with double power.', 1600, 'melee', 'unit', 'single', 1, 0, 0, 0),
  (17, 'wing-attack', 'Wing Attack', 10, 'physical', 60, 100, 35, 0, 'Inflicts regular damage.', 1900, 'melee', 'unit', 'single', 1, 0, 0, 0),
  (18, 'whirlwind', 'Whirlwind', 1, 'status', null, null, 20, -6, 'Switches the target out for another of its trainer’s Pokémon selected at random. Wild battles end immediately. Doesn’t affect Pokémon with Suction Cups or under the effect of Ingrain.', 2500, 'ranged', 'unit', 'single', 4, 0, 0, 0),
  (19, 'fly', 'Fly', 10, 'physical', 90, 95, 15, 0, 'Inflicts regular damage. User flies high into the air for one turn, becoming immune to attack, and hits on the second turn. During the immune turn, Gust, Hurricane, Sky Uppercut, Smack Down, Thunder, Twister, and Whirlwind still hit the user normally. Gust and Twister also have double power against the user. The damage from Hail and Sandstorm still applies during the immune turn. The user may be hit during its immune turn if under the effect of Lock-On, Mind Reader, or No Guard. This move cannot be used while Gravity is in effect. This move cannot be selected by Sleep Talk.', 2300, 'melee', 'unit', 'single', 1, 0, 0, 0),
  (20, 'bind', 'Bind', 1, 'physical', 15, 85, 20, 0, 'Inflicts regular damage. For the next 2–5 turns, the target cannot leave the field and is damaged for 1/16 its max HP at the end of each turn. The user continues to use other moves during this time. If the user leaves the field, this effect ends. Has a 3/8 chance each to hit 2 or 3 times, and a 1/8 chance each to hit 4 or 5 times. Averages to 3 hits per use. Rapid Spin cancels this effect.', 1300, 'melee', 'unit', 'single', 1, 0, 0, 0),
  (21, 'slam', 'Slam', 1, 'physical', 80, 75, 20, 0, 'Inflicts regular damage.', 2000, 'melee', 'unit', 'single', 1, 0, 0, 0),
  (22, 'vine-whip', 'Vine Whip', 5, 'special', 45, 100, 25, 0, 'Inflicts regular damage.', 2200, 'ranged', 'unit', 'single', 4, 0, 0, 0),
  (23, 'stomp', 'Stomp', 1, 'physical', 65, 100, 20, 0, 'Inflicts regular damage. Has a chance to make the target flinch. Power is doubled against Pokémon that have used Minimize since entering the field.', 1900, 'melee', 'unit', 'single', 1, 0, 0, 0),
  (24, 'double-kick', 'Double Kick', 7, 'physical', 30, 100, 30, 0, 'Inflicts regular damage. Hits twice in one turn.', 1500, 'melee', 'unit', 'single', 1, 0, 0, 0),
  (25, 'mega-kick', 'Mega Kick', 1, 'physical', 120, 75, 5, 0, 'Inflicts regular damage.', 2500, 'melee', 'unit', 'single', 1, 0, 0, 0),
  (26, 'jump-kick', 'Jump Kick', 7, 'physical', 100, 95, 10, 0, 'Inflicts regular damage. If this move misses, is blocked by Protect or Detect, or has no effect, the user takes damage equal to half of its max HP rounded down. This move cannot be used while Gravity is in effect.', 2400, 'melee', 'unit', 'single', 1, 0, 0, 0),
  (27, 'rolling-kick', 'Rolling Kick', 7, 'physical', 60, 85, 15, 0, 'Inflicts regular damage. Has a chance to make the target flinch.', 1900, 'melee', 'unit', 'single', 1, 0, 0, 0),
  (28, 'sand-attack', 'Sand Attack', 9, 'status', null, 100, 15, 0, 'Lowers the target’s accuracy by one stage.', 2500, 'ranged', 'unit', 'single', 4, 0, 0, 0),
