  (54, 'mist', 'Mist', 6, 'status', null, null, 30, 0, 'Pokémon on the user’s side of the field are immune to stat-lowering effects for five turns. Guard Swap, Heart Swap, and Power Swap may still be used. Defog used by an opponent will end this effect.', 2500, 'ranged', 'unit', 'single', 4, 0, 0, 0),
  (55, 'water-gun', 'Water Gun', 3, 'special', 40, 100, 25, 0, 'Inflicts regular damage.', 2100, 'ranged', 'unit', 'single', 4, 0, 0, 0),
