  (67, 'low-kick', 'Low Kick', 7, 'physical', null, 100, 20, 0, 'Inflicts regular damage. Power increases with the target’s weight in kilograms, to a maximum of 120. Target’s weight | Power --------------- | ----: Up to 10kg | 20 Up to 25kg | 40 Up to 50kg | 60 Up to 100kg | 80 Up to 200kg | 100 Above 200kg | 120', 1100, 'melee', 'unit', 'single', 1, 0, 0, 0),
  (68, 'counter', 'Counter', 7, 'physical', null, 100, 20, -5, 'Targets the last opposing Pokémon to hit the user with a physical move this turn. Inflicts twice the damage that move did to the user. If there is no eligible target, this move will fail. Type immunity applies, but other type effects are ignored. This move cannot be copied by Mirror Move, nor selected by Assist or Metronome.', 1100, 'melee', 'unit', 'single', 1, 0, 0, 0),
  (69, 'seismic-toss', 'Seismic Toss', 7, 'physical', null, 100, 20, 0, 'Inflicts damage equal to the user’s level. Type immunity applies, but other type effects are ignored.', 1100, 'melee', 'unit', 'single', 1, 0, 0, 0),
