  (73, 'leech-seed', 'Leech Seed', 5, 'status', null, 90, 10, 0, 'Plants a seed on the target that drains 1/8 of its max HP at the end of every turn and heals the user for the amount taken. Has no effect on Grass Pokémon. The seed remains until the target leaves the field. The user takes damage instead of being healed if the target has Liquid Ooze. Rapid Spin will remove this effect. This effect is passed on by Baton Pass.', 2500, 'ranged', 'unit', 'single', 4, 0, 0, 0),
  (74, 'growth', 'Growth', 1, 'status', null, null, 20, 0, 'Raises the user’s Attack and Special Attack by one stage each. During Sunny Day, raises both stats by two stages.', 2500, 'melee', 'self', 'single', 0, 0, 0, 0),
  (75, 'razor-leaf', 'Razor Leaf', 5, 'special', 55, 95, 25, 0, 'Inflicts regular damage. User’s critical hit rate is one level higher when using this move.', 2300, 'ranged', 'unit', 'single', 4, 0, 0, 0),
  (76, 'solar-beam', 'Solar Beam', 5, 'special', 120, 100, 10, 0, 'Inflicts regular damage. User charges for one turn before attacking. During Sunny Day, the charge turn is skipped. During Hail, Rain Dance, or Sandstorm, power is halved. This move cannot be selected by Sleep Talk.', 6200, 'ranged', 'tile', 'line', 5, 0, 5, 1),
